FormulaFieldDefinitions.FormulaFieldDefinition:
if {AC_MAST.AC_GSTNO} = "" then
    if {AC_MAST.AC_PANNO} <> "" then
    '                                        PanNo : ' & {AC_MAST.AC_PANNO} & '                State :  ' & {STATE_MAST.STATE_CODE} & ' - ' & {AC_MAST.AC_STATE}
    else
    '                                    State :  ' & {STATE_MAST.STATE_CODE} & ' - ' & {AC_MAST.AC_STATE}
else
   {AC_MAST.AC_GSTNO} &  '                 State :  ' & {STATE_MAST.STATE_CODE} & ' - ' & {AC_MAST.AC_STATE}

if {AC_MAST.AC_MOBILE} <> '' then
    'Mo : ' + {AC_MAST.AC_MOBILE}
else if {AC_MAST.AC_PHONE} <> '' then
    'Ph : ' + {AC_MAST.AC_MOBILE}
else
    'Mo : ' + {AC_MAST.AC_MOBILE2}
